import * as THREE from 'three/webgpu';
import { texture, uv, vec4, float, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const imageUrl = (config.assets && config.assets.imageUrl) || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const map = ctx.textureLoader.load(imageUrl);
  map.colorSpace = THREE.SRGBColorSpace;

  const grainAmount = uniform(0.035);

  const uvNode = uv();
  const texColor = texture(map, uvNode);

  // Simple procedural grain using a pseudo-random hash based on uv coordinates.
  const hashInput = uvNode.mul(1234.5678);
  const grain = hashInput.x.fract().mul(hashInput.y.fract()).fract().sub(0.5).mul(grainAmount);

  const finalColor = vec4(
    texColor.r.add(grain),
    texColor.g.add(grain),
    texColor.b.add(grain),
    texColor.a
  );

  material.colorNode = finalColor;

  const mesh = new THREE.Mesh(geometry, material);

  const pos = (config.scenePosition && config.scenePosition.position) || [-3.2, -0.3, 0];
  const rot = (config.scenePosition && config.scenePosition.rotation) || [0, 0, 0];
  const scl = (config.scenePosition && config.scenePosition.scale) || [1, 1, 1];

  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  mesh.name = 'hub-collection-card-1-plane';

  const primitives = (config.cinematicPrimitives || []);
  primitives.forEach((primitive) => {
    const fn = ctx.primitives[primitive.name];
    if (fn) {
      fn(mesh, primitive.params);
    }
  });

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
  };

  return mesh;
}
